#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    vector<int> getResults(vector<int>& nums, vector<vector<int>>& queries) {
        vector<int> arr = nums;
        vector<int> ans;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                arr[q[1]] = q[2];
            } else if (q[0] == 2) {
                int res = 0;
                for (int i = q[1]; i <= q[2]; ++i) res ^= arr[i];
                ans.push_back(res);
            } else if (q[0] == 3) {
                reverse(arr.begin() + q[1], arr.begin() + q[2] + 1);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] getResults(int[] nums, int[][] queries) {
        int[] arr = nums.clone();
        List<Integer> resList = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                arr[q[1]] = q[2];
            } else if (q[0] == 2) {
                int res = 0;
                for (int i = q[1]; i <= q[2]; i++) res ^= arr[i];
                resList.add(res);
            } else if (q[0] == 3) {
                int l = q[1], r = q[2];
                while (l < r) {
                    int tmp = arr[l]; arr[l] = arr[r]; arr[r] = tmp;
                    l++; r--;
                }
            }
        }
        int[] ans = new int[resList.size()];
        for (int i = 0; i < resList.size(); i++) ans[i] = resList.get(i);
        return ans;
    }
}

